// Package textutil provides helpers for character-encoding conversion and
// Unicode normalization, built on golang.org/x/text.
package textutil

import (
	"fmt"

	"golang.org/x/text/encoding"
	"golang.org/x/text/encoding/htmlindex"
	"golang.org/x/text/unicode/norm"
)

// lookup resolves an encoding by its WHATWG/IANA name (e.g. "shift_jis",
// "windows-1252", "iso-8859-1").
func lookup(name string) (encoding.Encoding, error) {
	enc, err := htmlindex.Get(name)
	if err != nil {
		return nil, fmt.Errorf("unknown encoding %q: %w", name, err)
	}
	return enc, nil
}

// DecodeToUTF8 converts bytes in the named encoding to a UTF-8 string.
func DecodeToUTF8(b []byte, from string) (string, error) {
	enc, err := lookup(from)
	if err != nil {
		return "", err
	}
	out, err := enc.NewDecoder().Bytes(b)
	if err != nil {
		return "", fmt.Errorf("decode from %s: %w", from, err)
	}
	return string(out), nil
}

// EncodeFromUTF8 converts a UTF-8 string to bytes in the named encoding.
// It returns an error if s contains characters the target cannot represent.
func EncodeFromUTF8(s, to string) ([]byte, error) {
	enc, err := lookup(to)
	if err != nil {
		return nil, err
	}
	out, err := enc.NewEncoder().Bytes([]byte(s))
	if err != nil {
		return nil, fmt.Errorf("encode to %s: %w", to, err)
	}
	return out, nil
}

// Form is a Unicode normalization form.
type Form = norm.Form

const (
	NFC  = norm.NFC
	NFD  = norm.NFD
	NFKC = norm.NFKC
	NFKD = norm.NFKD
)

// Normalize returns s in the given normalization form.
func Normalize(s string, f Form) string {
	return f.String(s)
}

// EqualNormalized reports whether a and b are canonically equivalent
// (equal after NFC normalization).
func EqualNormalized(a, b string) bool {
	return norm.NFC.String(a) == norm.NFC.String(b)
}
EOF
cat > textutil/textutil_test.go <<'EOF'
package textutil

import (
	"bytes"
	"testing"
)

func TestRoundTripShiftJIS(t *testing.T) {
	const s = "こんにちは"
	b, err := EncodeFromUTF8(s, "shift_jis")
	if err != nil {
		t.Fatal(err)
	}
	got, err := DecodeToUTF8(b, "shift_jis")
	if err != nil {
		t.Fatal(err)
	}
	if got != s {
		t.Fatalf("round trip = %q, want %q", got, s)
	}
}

func TestDecodeLatin1(t *testing.T) {
	got, err := DecodeToUTF8([]byte{0x63, 0x61, 0x66, 0xE9}, "iso-8859-1")
	if err != nil {
		t.Fatal(err)
	}
	if got != "café" {
		t.Fatalf("got %q, want %q", got, "café")
	}
}

func TestEncodeUnrepresentable(t *testing.T) {
	if _, err := EncodeFromUTF8("日本", "windows-1252"); err == nil {
		t.Fatal("expected error encoding CJK to windows-1252")
	}
}

func TestUnknownEncoding(t *testing.T) {
	if _, err := DecodeToUTF8([]byte("x"), "no-such-encoding"); err == nil {
		t.Fatal("expected error for unknown encoding")
	}
}

func TestNormalize(t *testing.T) {
	composed := "é"    // é
	decomposed := "é" // e + combining acute
	if got := Normalize(decomposed, NFC); got != composed {
		t.Errorf("NFC = %q, want %q", got, composed)
	}
	if got := Normalize(composed, NFD); got != decomposed {
		t.Errorf("NFD = %q, want %q", got, decomposed)
	}
	if got := Normalize("ﬁ", NFKC); got != "fi" { // ﬁ ligature
		t.Errorf("NFKC = %q, want %q", got, "fi")
	}
	if !EqualNormalized(composed, decomposed) {
		t.Error("EqualNormalized should be true")
	}
	if !bytes.Equal([]byte(Normalize("abc", NFC)), []byte("abc")) {
		t.Error("ASCII should be unchanged")
	}
}
EOF
